# region: fold
def fold(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: digest
def digest(xs):
    return [v for v in xs if v % 2 == 0]

# region: gather
def gather(xs):
    return [v * v for v in xs[1:]]

# region: sift
def sift(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: emit
def emit(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(sift(gather(digest(fold(raw)))))

